<!--
 * 消息路由规则列表页组件
 *
 * @path apps/message-web/src/views/route-rule/index.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为消费契约 API（page/create/update/deleteApi）。
-->
<script lang="ts" setup>
/**
 * 消息路由（列表页）
 * <p>消费后端契约 RouteRuleController（src/api/route-rule.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询路由规则，行操作「编辑」打开 route-rule-form.vue、「删除」调 deleteApi({id})。
 * 列字段以 MsgRouteRuleVO 为准。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h } from 'vue';
import { useI18n } from 'vue-i18n';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { deleteApi, page } from '#/api/routeRule';
import type { MsgRouteRuleVO } from '#/api/models';

import RouteRuleForm from './route-rule-form.vue';

defineOptions({ name: 'RouteRuleManagement' });

const { t } = useI18n();

const gridOptions: VxeTableGridOptions<MsgRouteRuleVO> = {
  columns: [
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'ruleCode', title: '规则编码', width: 150 },
    { field: 'ruleName', title: '规则名称', width: 180 },
    { field: 'bizType', title: '业务类型', width: 110 },
    { field: 'channel', title: '触发通道', width: 100 },
    { field: 'targetChannel', title: '目标通道', width: 110 },
    { field: 'fallbackChannel', title: '兜底通道', width: 110 },
    { field: 'priority', title: '优先级', width: 80 },
    {
      field: 'status',
      title: t('common.status'),
      width: 90,
      slots: {
        default: ({ row }) =>
          h(
            ElTag,
            { type: row.status === 'DISABLED' ? 'info' : 'success' },
            () => row.status ?? '-',
          ),
      },
    },
    { field: 'createdAt', title: t('common.createTime'), width: 170 },
    {
      field: 'action',
      title: t('common.actions'),
      width: 140,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) },
              () => t('common.edit'),
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => t('common.delete'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'ruleName',
        title: '规则名称',
        itemRender: { name: 'Input', props: { placeholder: '规则名称' } },
      },
      {
        field: 'ruleCode',
        title: '规则编码',
        itemRender: { name: 'Input', props: { placeholder: '规则编码' } },
      },
      {
        field: 'status',
        title: t('common.status'),
        itemRender: { name: 'Input', props: { placeholder: t('common.status') } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [RouteRuleFormModal, routeRuleFormApi] = useYDSZModal({ connectedComponent: RouteRuleForm });

function handleAdd() {
  routeRuleFormApi.open();
}

function handleEdit(row: MsgRouteRuleVO) {
  routeRuleFormApi.setData({ record: row });
  routeRuleFormApi.open();
}

async function handleDelete(row: MsgRouteRuleVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(`确定删除路由规则「${row.ruleName}」吗？`, t('deleteConfirmTitle'), {
      type: 'warning',
    });
  } catch {
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await deleteApi({ id: row.id });
    ElMessage.success(t('deleteSuccess'));
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="路由规则">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">{{ t('common.create') }}</ElButton>
      </template>
    </Grid>
    <RouteRuleFormModal @success="gridApi.query()" />
  </Page>
</template>
